sys_ui_action.script:
(function unlockSubmission() {
    var submissionId = current.getValue('submission');
    if (!submissionId) {
        gs.addErrorMessage('Unlock failed: no submission is linked to this task.');
        action.setRedirectURL(current);
        return;
    }

    var sub = new GlideRecord('x_gegis_ins_policy_submission');
    if (!sub.get(submissionId)) {
        gs.addErrorMessage('Unlock failed: linked submission no longer exists.');
        action.setRedirectURL(current);
        return;
    }

    sub.is_locked = false;
    sub.update();

    // Close the HITL task as Closed Complete (state 3).
    current.state = 3;
    current.active = false;
    current.work_notes = 'Submission ' + sub.getDisplayValue('number') + ' unlocked; task closed complete.';
    current.update();

    gs.addInfoMessage('Submission ' + sub.getDisplayValue('number') + ' unlocked. Task ' +
        current.getValue('number') + ' closed complete.');
    action.setRedirectURL(current);
})();
